import os
import glob

base_dirs = [
    '/home/shared-user/研究生/QGIS-agent/数据/',
    '/home/shared-user/研究生/QGIS-agent/',
]

for base in base_dirs:
    if os.path.exists(base):
        print(f"\n=== {base} ===")
        for root, dirs, files in os.walk(base):
            # 限制深度，避免过深
            depth = root.replace(base, '').count(os.sep)
            if depth > 5:
                continue
            geo_files = [f for f in files if any(f.lower().endswith(ext) for ext in ['.shp','.gpkg','.geojson','.tif','.tiff','.csv','.dxf','.kml','.gml','.json','.gdb','.xml','.osm','.pbf'])]
            if geo_files or depth <= 2:
                if geo_files:
                    print(f"\n  {root}/ [地理数据]")
                    for f in sorted(geo_files):
                        full = os.path.join(root, f)
                        try:
                            size = os.path.getsize(full)
                            print(f"    {f} ({size/1024:.1f} KB)")
                        except:
                            print(f"    {f}")
                elif depth <= 1:
                    # 显示子目录结构
                    for d in dirs:
                        print(f"  {d}/")
    else:
        print(f"路径不存在: {base}")

from qgis.core import QgsProject
from pathlib import Path

base = Path('/home/shared-user/研究生/QGIS-agent/数据/')
print(f"检查目录: {base}")
print(f"存在: {base.exists()}")
if base.exists():
    for item in sorted(base.rglob('*')):
        depth = len(item.relative_to(base).parts)
        if depth <= 5:
            suffix = item.suffix.lower()
            is_geo = suffix in ['.shp','.gpkg','.geojson','.tif','.tiff','.csv','.dxf','.kml','.gml','.json','.gdb','.xml','.osm','.pbf']
            if is_geo:
                try:
                    size_kb = item.stat().st_size / 1024
                    print(f"  [地理] {item} ({size_kb:.1f} KB)")
                except:
                    print(f"  [地理] {item}")
            elif item.is_dir() and depth <= 2:
                print(f"  [目录] {item}/")
